import{_ as t,o as d,c as r,a2 as a}from"./chunks/framework.BM5YPQmL.js";const m=JSON.parse('{"title":"QEMU coupling inventory","description":"","frontmatter":{},"headers":[],"relativePath":"reference/qemu-coupling-inventory.md","filePath":"reference/qemu-coupling-inventory.md"}'),o={name:"reference/qemu-coupling-inventory.md"};function i(s,e,c,n,h,l){return d(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="qemu-coupling-inventory" tabindex="-1">QEMU coupling inventory <a class="header-anchor" href="#qemu-coupling-inventory" aria-label="Permalink to &quot;QEMU coupling inventory&quot;">​</a></h1><p>Every registration of an accommodation to the QEMU acceptance platform in the engineering tree, collected by <code>tools/audit/scan_qemu_coupling.sh</code> (read-only scan) and classified by <code>tools/audit/curate_qemu_inventory.py</code>. Collection only - nothing was modified, moved or deleted by the audit.</p><h2 id="method-and-coverage" tabindex="-1">Method and coverage <a class="header-anchor" href="#method-and-coverage" aria-label="Permalink to &quot;Method and coverage&quot;">​</a></h2><ul><li>Scanner: <code>tools/audit/scan_qemu_coupling.sh</code> (A/B pattern set + a catch-all mention class; per-file coverage record emitted alongside).</li><li>Classification: rule-based by zone and shape, plus a hand-curated override table - every override entry was verified by reading the code at that line.</li><li>Boundary rule honored: a driver written to a published virtual-hardware SPEC (virtio, xHCI class code, PIIX4, i6300ESB - all real parts/specs) is NOT counted as coupling; such entries are recorded as observations or excluded with a stated reason.</li></ul><h2 id="reconciliation" tabindex="-1">Reconciliation <a class="header-anchor" href="#reconciliation" aria-label="Permalink to &quot;Reconciliation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Measure</th><th>Count</th></tr></thead><tbody><tr><td>Raw scanner hits</td><td>2338</td></tr><tr><td>Classified entries</td><td>2338</td></tr><tr><td>A/B-class entries (significant)</td><td>212</td></tr></tbody></table><p>Class distribution: <code>{&quot;DOC&quot;: 1426, &quot;CMT&quot;: 664, &quot;B6&quot;: 97, &quot;B4&quot;: 12, &quot;B2&quot;: 60, &quot;FIX&quot;: 10, &quot;B3&quot;: 4, &quot;A5&quot;: 11, &quot;B1&quot;: 24, &quot;A1&quot;: 4, &quot;TOOL&quot;: 26}</code></p><h2 id="live-verification-a-b-entries-actually-firing" tabindex="-1">Live verification (A/B entries actually firing) <a class="header-anchor" href="#live-verification-a-b-entries-actually-firing" aria-label="Permalink to &quot;Live verification (A/B entries actually firing)&quot;">​</a></h2><p>Four audited entries were triggered in a live boot of the release ISO with the coupling-relevant devices attached (transcripts: <code>evidence/qemu-coupling-audit/</code>):</p><table tabindex="0"><thead><tr><th>Class</th><th>Entry</th><th>Live proof (verbatim console line)</th></tr></thead><tbody><tr><td>A1</td><td><code>real_hw_test</code> CPUID hypervisor branch</td><td><code>[real_hw_test] actual: hypervisor bit set (QEMU/sandbox)</code></td></tr><tr><td>A5</td><td>virtio-blk 1AF4:1004 PCI-ID match</td><td><code>[virtio_blk_test] capacity nonzero (legacy cfg @0x14) =&gt; PASS</code></td></tr><tr><td>B2</td><td>e1000 legacy register-init path</td><td><code>e1000: HWaddr 52:54:00:12:34:56 ... link: UP</code></td></tr><tr><td>B2</td><td>e1000 S3 resume replay (existing rings, same MAC)</td><td><code>SLEEP_ARMED set ... Resumed from S3 ... e1000: (same MAC) link: UP</code></td></tr></tbody></table><h2 id="family-analyses-per-category" tabindex="-1">Family analyses (per category) <a class="header-anchor" href="#family-analyses-per-category" aria-label="Permalink to &quot;Family analyses (per category)&quot;">​</a></h2><h3 id="a5" tabindex="-1">A5 <a class="header-anchor" href="#a5" aria-label="Permalink to &quot;A5&quot;">​</a></h3><p>PCI-ID whitelists: the virtio (1AF4:1059/1004), qemu-xhci (1b36:000D) and EHCI entries ride CLASS-driven matches that cover the QEMU model AND real silicon (xhci: class 0x0C0330 &#39;covers qemu-xhci, nec-usb-xhci, real HW&#39;; i801 PIIX4 8086:7113 is a real Intel part). Per the boundary rule these are standard-spec drivers, recorded as observations.</p><h3 id="b2" tabindex="-1">B2 <a class="header-anchor" href="#b2" aria-label="Permalink to &quot;B2&quot;">​</a></h3><p>The e1000/e1000e family comments (bus-master-last ordering, RDT ring-full rule) document register orderings QEMU&#39;s models require; the same orderings are within the Intel datasheet sequences, so real NICs execute them unchanged.</p><h3 id="b4" tabindex="-1">B4 <a class="header-anchor" href="#b4" aria-label="Permalink to &quot;B4&quot;">​</a></h3><p>Firmware-behavior notes (ACPI 1.0 RSDT pointer, AML subset, SeaBIOS resume-vector convention, OVMF load-address relocation) describe what the QEMU firmwares do; the code paths are spec-driven (RSDP/XSDT parse, relocation-safe PE) and the notes record where the behavior was observed.</p><h3 id="b6" tabindex="-1">B6 <a class="header-anchor" href="#b6" aria-label="Permalink to &quot;B6&quot;">​</a></h3><p>Acceptance batteries drive QEMU from the host; the OS image itself carries no emulator dependency.</p><h2 id="significant-entries-verified-by-code-reading" tabindex="-1">Significant entries (verified by code reading) <a class="header-anchor" href="#significant-entries-verified-by-code-reading" aria-label="Permalink to &quot;Significant entries (verified by code reading)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Line</th><th>Class</th><th>Real-machine impact</th><th>Blocking?</th></tr></thead><tbody><tr><td><code>ocbl/efi/efi_entry.c</code></td><td>353</td><td>B4</td><td>the UEFI entry calls SetWatchdogTimer(0) before ExitBootServices - OVMF arms a 5-minute firmware watchdog; real UEFI firmware also arms it and the same call disarms it (a UEFI-spec service)</td><td>no (spec service, required on real firmware too)</td></tr><tr><td><code>ocire/ocire_wdt.c</code></td><td>62</td><td>B2</td><td>the comment describes QEMU&#39;s MMIO BAR0; the code accepts BOTH the MMIO and the I/O BAR flavors (&#39;real 6300ESB boards may use an I/O BAR - both are accepted here&#39;)</td><td>no (explicit real-machine handling)</td></tr><tr><td><code>ocos/drivers/audio/drv_audio_hda.c</code></td><td>498</td><td>B3</td><td>RIRBCTL.IRQ_EN stays on because QEMU&#39;s HDA model only clears its response counter when the guest write-clears RIRBSTS.IRQ (which requires the enable); the controller IRQ line stays quiet because INTCTL.CIE is off - real HDA controllers accept the same setting</td><td>no</td></tr><tr><td><code>ocos/drivers/bus/drv_bus_acpi_power.c</code></td><td>225</td><td>B1</td><td>the resume trampoline page 0x8000 is placed below the EBDA whose top is cited as 0x9FC00 &#39;on QEMU&#39;; firmware with a higher EBDA could overlap the page</td><td>possible (S3 resume on non-QEMU firmware must re-check the EBDA top)</td></tr><tr><td><code>ocos/drivers/bus/drv_bus_pcie.c</code></td><td>273</td><td>B1</td><td>unassigned-BAR allocation starts at 0xC0000000 with a comment placing it below the QEMU ECAM window; a real machine with dense low-MMIO firmware reservations could collide with the pool</td><td>possible (real-machine bring-up must re-derive the pool from the firmware MMIO map)</td></tr><tr><td><code>ocos/drivers/usb/drv_usb_ehci.c</code></td><td>626</td><td>B3</td><td>the port-speed decode treats an EHCI-enabled port as high-speed (QEMU sets PED at reset completion only for HS devices; standard EHCI silicon is HS-only per spec - the Linux driver does the same)</td><td>no</td></tr><tr><td><code>ocos/kernel/arch/arm64/boot.S</code></td><td>10</td><td>B1</td><td>arm64 bring-up parks secondary harts as QEMU -smp presents them at 0x40000000; the port targets the QEMU virt machine only (declared bring-up scope)</td><td>yes for real arm64 hardware (by design, bring-up)</td></tr><tr><td><code>ocos/kernel/arch/arm64/kernel_main.c</code></td><td>11</td><td>B1</td><td>arm64 console is the QEMU virt PL011 at 0x09000000 (primecell per the ARM spec, but the address is the virt-machine layout)</td><td>yes for real arm64 hardware (by design, bring-up)</td></tr><tr><td><code>ocos/kernel/arch/arm64/kernel_main.c</code></td><td>21</td><td>B1</td><td>same PL011 base constant</td><td>yes for real arm64 hardware (by design)</td></tr><tr><td><code>ocos/kernel/arch/riscv/boot.S</code></td><td>6</td><td>B1</td><td>riscv bring-up assumes the QEMU virt machine loads the image at 0x80000000 in M-mode</td><td>yes for real riscv hardware (by design, bring-up)</td></tr><tr><td><code>ocos/kernel/arch/riscv/kernel_main.c</code></td><td>11</td><td>B1</td><td>riscv console is the QEMU virt NS16550A at 0x10000000</td><td>yes for real riscv hardware (by design)</td></tr><tr><td><code>ocos/kernel/arch/riscv/kernel_main.c</code></td><td>23</td><td>B1</td><td>same NS16550A base constant</td><td>yes for real riscv hardware (by design)</td></tr><tr><td><code>ocos/services/block/src/svc_block_cmds_test.c</code></td><td>573</td><td>A1</td><td>real_hw_test branches on the CPUID hypervisor bit; the bare-metal path exists and is complete (prints the AHCI/ATA/NVMe/NIC/sound/USB driver states)</td><td>no</td></tr><tr><td><code>ocos/services/block/src/svc_block_cmds_test.c</code></td><td>582</td><td>A1</td><td>same branch: under a hypervisor the command reports NOT RUN (needs bare metal) instead of the driver report</td><td>no</td></tr><tr><td><code>ocos/services/block/src/svc_block_cmds_test.c</code></td><td>583</td><td>A1</td><td>report text of the hypervisor branch</td><td>no</td></tr><tr><td><code>ocos/services/crash/src/svc_crash_watchdog.c</code></td><td>154</td><td>B1</td><td>comment cites the QEMU ACPI table placement (0x400000-0x600000) for the RSDT read window; the read goes through the kernel identity map of the cached table phys, which the MCFG/RSDT parse discovered</td><td>no (the phys address is parsed, not hardcoded)</td></tr><tr><td><code>ocos/services/crash/src/svc_crash_watchdog.c</code></td><td>206</td><td>B1</td><td>the TCO probe reads the LPC bridge at the fixed slot 00:1f.0 (Intel convention, q35 ICH9 cited); non-Intel chipsets place the LPC elsewhere</td><td>possible (TCO watchdog absent on non-Intel boards; the i6300esb path is the fallback)</td></tr><tr><td><code>ocos/services/net/src/svc_net_core.c</code></td><td>6394</td><td>B2</td><td>the S3 resume replay re-programs the legacy e1000 (8086:100E, QEMU&#39;s default NIC) against the surviving rings; the replay mirrors the init sequence exactly and keeps the same MAC - a real NIC that survives suspend differently would still be re-programmed through the same path</td><td>no</td></tr><tr><td><code>ocos/services/power/src/svc_power_core.c</code></td><td>133</td><td>B1</td><td>the hardcoded 0x604/0xB004/0xF000 writes run only AFTER the primary FADT+_S5 ACPI path fails; real machines take the ACPI path</td><td>no (fallback only)</td></tr></tbody></table><h2 id="boundary-rule-exclusions-false-positives-with" tabindex="-1">Boundary-rule exclusions (false positives, with <a class="header-anchor" href="#boundary-rule-exclusions-false-positives-with" aria-label="Permalink to &quot;Boundary-rule exclusions (false positives, with&quot;">​</a></h2><p>reasons)</p><table tabindex="0"><thead><tr><th>File</th><th>Line</th><th>Reason</th></tr></thead><tbody><tr><td><code>ocire/generated/ocire_cn_font_data.c</code></td><td>7774</td><td>font glyph data: the bytes are CJK glyph indexes that coincide with the i440FX device-id constant</td></tr><tr><td><code>ocire/generated/ocire_cn_font_data.c</code></td><td>8541</td><td>same font-data coincidence</td></tr><tr><td><code>ocos/drivers/input/drv_input_i2chid.h</code></td><td>15</td><td>the comment notes QEMU has no i2c-hid model; the probe path is identical on real hardware (finds zero devices under QEMU and reports honestly)</td></tr><tr><td><code>ocos/services/camera/src/svc_camera_cmds_scsi.c</code></td><td>193</td><td>parser golden-check fixture: synthetic QEMU-style INQUIRY bytes fed to the generic parser; no runtime device-identity matching</td></tr><tr><td><code>ocos/services/camera/src/svc_camera_cmds_scsi.c</code></td><td>199</td><td>same fixture (vendor field bytes)</td></tr><tr><td><code>ocos/services/camera/src/svc_camera_cmds_scsi.c</code></td><td>200</td><td>same fixture (product field bytes)</td></tr><tr><td><code>ocos/services/camera/src/svc_camera_cmds_scsi.c</code></td><td>205</td><td>same fixture (expected parse result)</td></tr><tr><td><code>ocse/chinese/chinese_font_data.c</code></td><td>7774</td><td>same font-data coincidence</td></tr><tr><td><code>ocse/chinese/chinese_font_data.c</code></td><td>8541</td><td>same font-data coincidence</td></tr><tr><td><code>ocse/drivers/input/driver_input_i2chid.h</code></td><td>15</td><td>same as the OCOS-side note</td></tr></tbody></table><p>The complete per-hit register (every raw hit with its classification) is the machine-readable output of the curator; the counts above reconcile hit-for-hit.</p>',25)])])}const p=t(o,[["render",i]]);export{m as __pageData,p as default};
